            }
          },
          "large": {
            "required": false,
            "tsType": {
              "name": "boolean"
            },
            "description": "Is the button large?",
            "defaultValue": {
              "value": "false",
              "computed": false
            }
          },
          "icon": {
            "required": false,
            "tsType": {
              "name": "union",
              "raw": "| 'arrow-right'\n| 'arrow-left'\n| 'cross'\n| 'cart'\n| 'minus'\n| 'plus'\n| 'moon'\n| 'sun'\n| 'star'",
              "elements": [
                {
                  "name": "literal",
                  "value": "'arrow-right'"
                },
                {
                  "name": "literal",
                  "value": "'arrow-left'"
                },
                {
                  "name": "literal",
                  "value": "'cross'"
                },
                {
                  "name": "literal",
                  "value": "'cart'"
                },
                {
                  "name": "literal",
                  "value": "'minus'"
                },
                {
                  "name": "literal",
                  "value": "'plus'"
                },
                {
                  "name": "literal",
                  "value": "'moon'"
                },
                {
                  "name": "literal",
                  "value": "'sun'"
                },
                {
                  "name": "literal",
                  "value": "'star'"
                }
              ]
            },
            "description": "Does the button have an icon?"
          },
          "iconSize": {
            "required": false,
            "tsType": {
              "name": "number"
            },
            "description": "Size of the icon"
          },
