                },
                {
                  "name": "ReactReactNode",
                  "raw": "React.ReactNode"
                }
              ]
            },
            "description": "The content of the button"
          },
          "onClick": {
            "required": false,
            "tsType": {
              "name": "signature",
              "type": "function",
              "raw": "() =\u003E void",
              "signature": {
                "arguments": [],
