		assert.ok(!radio3.checked);

		component.radio = 'radio1';

		assert.ok(radio1.checked);
		assert.ok(!radio2.checked);
		assert.ok(!radio3.checked);

		await radio3.dispatchEvent(event);

		assert.equal(component.radio, 'radio3');
		assert.ok(!radio1.checked);
		assert.ok(!radio2.checked);
