		flushSync();

		assert.equal(component.value, 5.5);
		assert.equal(input.value, '5.5');

		input.value = '5.50';
		input.dispatchEvent(inputEvent);
		flushSync();

		assert.equal(component.value, 5.5);
		assert.equal(input.value, '5.50');

		component.value = 1;
		assert.equal(component.value, 1);
		assert.equal(input.value, '1');
	}
});

