export default test({
	get props() {
		return {
			visible: false,
			things: ['a', 'b', 'c', 'd']
		};
	},

	// intro: true,

	html: `
		<p>waiting...</p>
	`,

	async test({ assert, component, target, raf }) {
		component.visible = true;

		assert.htmlEqual(
			target.innerHTML,
			`
			<p>introstart</p>
			<p>a</p>
			<p>b</p>
			<p>c</p>
			<p>d</p>
		`
		);

