			target.innerHTML,
			'<button>toggle</button><button>run</button><p>hello: 1</p>'
		);

		flushSync(() => run.click());
		assert.htmlEqual(
			target.innerHTML,
			'<button>toggle</button><button>run</button><p>hello: 2</p>'
		);

		assert.deepEqual(logs, ['aborted']);
	}
});

